import { Check } from "lucide-react";
import type { ComponentProps, ReactNode } from "react";
import { useId } from "react";
import { cn } from "@/lib/cn";

/**
 * Same API and geometry as the kit Checkbox (20px, 2px radius, ink when checked),
 * but draws the tick with an icon (the kit's background-image tick was not
 * generated by Tailwind, so checked boxes showed no tick).
 * Workaround until the kit is fixed (see report).
 */
export function TickCheckbox({
  label,
  description,
  className,
  id: idProp,
  error,
  ...props
}: { label: ReactNode; description?: ReactNode; error?: string | null } & Omit<ComponentProps<"input">, "type">) {
  const auto = useId();
  const id = idProp ?? auto;
  return (
    <div className={cn("flex flex-col gap-1", className)}>
      <label htmlFor={id} className="flex min-h-touch cursor-pointer items-start gap-3 py-2.5">
        <span className="relative mt-0.5 inline-flex size-5 shrink-0">
          <input
            id={id}
            type="checkbox"
            className="peer size-5 appearance-none rounded-xs border border-line-strong bg-surface-raised transition-colors checked:border-ink checked:bg-ink aria-invalid:border-danger"
            aria-invalid={error ? true : undefined}
            aria-describedby={error ? `${id}-error` : undefined}
            {...props}
          />
          <Check
            aria-hidden
            size={16}
            strokeWidth={2}
            absoluteStrokeWidth
            className="pointer-events-none absolute top-0.5 left-0.5 text-ink-inverse opacity-0 transition-opacity duration-instant peer-checked:opacity-100"
          />
        </span>
        <span className="flex flex-col gap-0.5">
          <span className="type-body-s text-ink">{label}</span>
          {description ? <span className="type-caption text-ink-muted">{description}</span> : null}
        </span>
      </label>
      {error ? (
        <p id={`${id}-error`} className="type-caption text-danger">
          {error}
        </p>
      ) : null}
    </div>
  );
}
